const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const windhoek = ee.Geometry.Point([17.0832, -22.5700]); // Windhoek coordinates
  const region = windhoek.buffer(50000); // 50km buffer around Windhoek

  // 2. Data Acquisition - MODIS Vegetation Indices
  const modisCol = ee.ImageCollection('MODIS/061/MOD13Q1');

  // Function to get February NDVI for a specific year
  function getFebNDVI(year) {
    const startDate = ee.Date.fromYMD(year, 1, 1); // Feb 1
    const endDate = startDate.advance(1, 'month'); // Mar 1
    return modisCol
      .filterDate(startDate, endDate)
      .select('NDVI')
      .mean()
      .multiply(0.0001); // Scale factor for MODIS NDVI
  }

  // Get 2021 NDVI
  const ndvi2021 = getFebNDVI(2021);

  // Get 2010-2020 average NDVI
  const years = ee.List.sequence(2010, 2020);
  const historicalNDVI = years.map(year => getFebNDVI(year));
  const avgHistorical = ee.ImageCollection.fromImages(historicalNDVI).mean();

  // Check data availability
  const count2021 = modisCol.filterDate('2021-02-01', '2021-03-01').size();
  const countHistorical = modisCol.filterDate('2010-02-01', '2021-02-01')
    .filter(ee.Filter.calendarRange(1, 1, 'month')).size(); // February only

  const count2021Info = count2021.getInfo();
  const countHistoricalInfo = countHistorical.getInfo();

  print(`2021 February images: ${count2021Info}`);
  print(`2010-2020 February images: ${countHistoricalInfo}`);

  if (count2021Info === 0 || countHistoricalInfo === 0) {
    print("C1: Empty Collection");
    return;
  }

  // Calculate regional means
  const stats2021 = ndvi2021.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const statsHistorical = avgHistorical.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const ndvi2021Val = stats2021.get('NDVI').getInfo();
  const ndviHistoricalVal = statsHistorical.get('NDVI').getInfo();

  // Check for valid pixels
  if (ndvi2021Val === null || ndviHistoricalVal === null) {
    print("C2: No Valid Pixels");
    return;
  }

  // Validate NDVI range
  if (Math.abs(ndvi2021Val) > 1 || Math.abs(ndviHistoricalVal) > 1 || 
      isNaN(ndvi2021Val) || isNaN(ndviHistoricalVal)) {
    print("C3: Calculation Failure");
    return;
  }

  // Print evidence and determine answer
  print(`2021 Feb NDVI: ${ndvi2021Val.toFixed(3)}`);
  print(`2010-2020 Avg Feb NDVI: ${ndviHistoricalVal.toFixed(3)}`);
  print(`Difference: ${(ndvi2021Val - ndviHistoricalVal).toFixed(3)}`);

  if (ndvi2021Val > ndviHistoricalVal) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
